solutions.naive:
class Solution:
    def matrixScore(self, grid: list[list[int]]) -> int:
        m, n = len(grid), len(grid[0])
        best = 0
        for mask in range(1 << m):
            total = 0
            for c in range(n):
                ones = 0
                for r in range(m):
                    bit = grid[r][c]
                    if (mask >> r) & 1:
                        bit ^= 1
                    ones += bit
                ones = max(ones, m - ones)
                total += ones * (1 << (n - 1 - c))
            best = max(best, total)
        return best

solutions.better:
class Solution:
    def matrixScore(self, grid: list[list[int]]) -> int:
        mat = [row[:] for row in grid]
        m, n = len(mat), len(mat[0])
        for r in range(m):
            if mat[r][0] == 0:
                for c in range(n):
                    mat[r][c] ^= 1
        for c in range(1, n):
            ones = sum(mat[r][c] for r in range(m))
            if ones < m - ones:
                for r in range(m):
                    mat[r][c] ^= 1
        score = 0
        for row in mat:
            value = 0
            for bit in row:
                value = value * 2 + bit
            score += value
        return score

