class Solution:
    def matrixScore(self, grid: list[list[int]]) -> int:
        m, n = len(grid), len(grid[0])
        score = m * (1 << (n - 1))
        for c in range(1, n):
            ones = 0
            for r in range(m):
                bit = grid[r][c]
                if grid[r][0] == 0:
                    bit ^= 1
                ones += bit
            score += max(ones, m - ones) * (1 << (n - 1 - c))
        return score

